/* PintsNow app part: Groups sheets + top list. Moved from app.js without change (W2 step 4). Shared state: PN.s (app-core.js). */
(function () {
  "use strict";
  var PN = window.PN;
  // <split:imports> generated by scripts/split/move.mjs — do not edit
  var U, I, t, LIVE, $;
  PN.link(function () { U = PN.U; I = PN.I; t = PN.t; LIVE = PN.LIVE; $ = PN.$; });
  function mods() { return PN.mods.apply(null, arguments); }
  function rpc() { return PN.rpc.apply(null, arguments); }
  function parseData() { return PN.parseData.apply(null, arguments); }
  function toast() { return PN.toast.apply(null, arguments); }
  function errMsg() { return PN.errMsg.apply(null, arguments); }
  function openSheet() { return PN.openSheet.apply(null, arguments); }
  function el() { return PN.el.apply(null, arguments); }
  function btn() { return PN.btn.apply(null, arguments); }
  function copyText() { return PN.copyText.apply(null, arguments); }
  function flyTo() { return PN.flyTo.apply(null, arguments); }
  function skalCount() { return PN.skalCount.apply(null, arguments); }
  function barTypeLabel() { return PN.barTypeLabel.apply(null, arguments); }
  function maxLevel() { return PN.maxLevel.apply(null, arguments); }
  function whoOf() { return PN.whoOf.apply(null, arguments); }
  function placeLabel() { return PN.placeLabel.apply(null, arguments); }
  function friendsDrinking() { return PN.friendsDrinking.apply(null, arguments); }
  function beerOnly() { return PN.beerOnly.apply(null, arguments); }
  function refresh() { return PN.refresh.apply(null, arguments); }
  function getName() { return PN.getName.apply(null, arguments); }
  function withName() { return PN.withName.apply(null, arguments); }
  function notifPromptOnce() { return PN.notifPromptOnce.apply(null, arguments); }
  function showInvite() { return PN.showInvite.apply(null, arguments); }
  function showInstallGuide() { return PN.showInstallGuide.apply(null, arguments); }
  PN.put({ showGroups: showGroups, showJoin: showJoin });
  // </split:imports>

  /* ---------- Groups ---------- */
  function joinLink(code) { return location.origin + location.pathname + "?join=" + encodeURIComponent(code); }
  function friendsNowText() { var f = friendsDrinking(); return f ? " · " + t("friendsNow", f) : ""; }

  // Group order: the group you chat with most comes first (owner wish). Local score per group:
  // open chat +1, send +3, halves every 5 days. Ties keep the server order.
  var GACT_KEY = "olnu.gact", GACT_HALF = 5 * 864e5;
  function gactScore(rec) { return rec ? rec.s * Math.pow(0.5, (Date.now() - rec.t) / GACT_HALF) : 0; }
  window.olnuGroupBump = function (id, w) {
    if (!id) return;
    var all = U.ls.getJSON(GACT_KEY, {}) || {}, k = String(id);
    all[k] = { s: gactScore(all[k]) + (w || 1), t: Date.now() };
    U.ls.setJSON(GACT_KEY, all);
  };
  function sortGroupsByChat(gs) {
    var all = U.ls.getJSON(GACT_KEY, {}) || {};
    return gs.map(function (g, i) { return { g: g, i: i, s: gactScore(all[String(g.id)]) }; })
      .sort(function (a, b) { return b.s - a.s || a.i - b.i; }).map(function (x) { return x.g; });
  }
  function showGroups() {
    if (!LIVE) {
      openSheet(t("groups"), function (body) { body.appendChild(el("div", { class: "info", text: t("soonInfo") })); });
      return;
    }
    withName(function () {
      openSheet(t("groups"), function (body) {
        var list = el("ul", { class: "glist" });
        // ux3: the name + "Byt namn" live in 👤 Profil only (owner 2026-11-07).
        body.appendChild(el("h3", { text: t("myGroups") + friendsNowText() }));
        body.appendChild(list);
        body.appendChild(el("div", { class: "row", style: "margin-top:14px" }, [
          btn(t("create"), "btn-amber", showCreate), btn(t("join"), "btn-green", function () { showJoin(""); })
        ]));
        if (!window.JOIN) body.appendChild(el("div", { class: "row", style: "margin-top:8px" }, [btn("📲 " + t("inviteBtn"), "btn-block", showInvite)]));   // join.js: ➕ per group + Vänner tab
        mods("groupsSheet", body);   // "Kom hit!"
        list.appendChild(el("li", { class: "muted", text: "…" }));
        groupsList = list;   // cifix3: set at once: a fresh answer that lands before the cached rows are drawn is kept (list.__fresh) and patched in
        rpc("my_groups").then(function (r) {
          list.innerHTML = "";
          if (r.error) { list.appendChild(el("li", { class: "muted", text: t("fail") })); return; }
          fillGroups(list, r.data || []);
          list.__filled = 1;
          if (list.__fresh && list.isConnected && !list.__one && list.__fresh.length > 1) { var fr = list.__fresh, tp = el("ul", { class: list.className }); fillGroups(tp, fr); if (window.WARM) window.WARM.patch(list, tp); }
          list.__fresh = null;
        });
      });
    });
  }
  // inst: the list body, also used for an in-place update when warm.js brings a newer my_groups.
  var groupsList = null;
  function fillGroups(list, gs) {
    if (!gs.length) { list.appendChild(el("li", { class: "muted", text: t("noGroups") })); return; }
    // Owner: "I want to see all the groups, not the options. Tap a group, then see the options."
    // One group: show it open as before. Several: a short card per group; a tap opens that group's page.
    // ds60: always cards; a group opens on its own page (no create / join rows under an open group)
    list.__one = false;
    sortGroupsByChat(gs).forEach(function (g) { list.appendChild(groupCard(g)); });
  }
  window.addEventListener("olnu:warm", function (e) {
    var d = e.detail || {};
    if (d.fn !== "my_groups" || !groupsList || !groupsList.isConnected || !Array.isArray(d.data) || !window.WARM) return;
    if (!groupsList.__filled) { groupsList.__fresh = d.data; return; }   // cifix3: rows not drawn yet
    if (groupsList.__one || d.data.length < 2) return;   // the open single-group card holds module state: next open
    var tmp = el("ul", { class: groupsList.className }); fillGroups(tmp, d.data);
    window.WARM.patch(groupsList, tmp);   // only the changed values move (count, "● 3 av 5"), no list rebuild
  });
  function groupCard(g) {
    var n = g.active_count | 0;
    var li = el("li", { class: "gitem gcard", role: "button", tabindex: "0", "aria-label": g.name }, [
      el("div", { class: "gcard-main" }, [
        el("div", { class: "gname", text: g.name }),
        el("div", { class: "gsub", html: (n ? '<span class="gcard-live">● </span>' : "") + t("drinkingOf", n, g.member_count | 0) })
      ]),
      el("span", { class: "gcard-go", "aria-hidden": "true", text: "›" })
    ]);
    mods("groupCard", g, li);   // join.js: ➕ Bjud in
    var open = function () { showGroupPage(g); };
    li.addEventListener("click", open);
    li.addEventListener("keydown", function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(); } });
    return li;
  }
  function showGroupPage(g) {
    try { window.olnuGroupBump(g.id, 0.5); } catch (e) {}
    openSheet(g.name, function (body) {
      body.appendChild(el("button", { type: "button", class: "g-back", text: "‹ " + t("myGroups"), onclick: showGroups }));
      var list = el("ul", { class: "glist" });
      list.appendChild(groupItem(g));
      body.appendChild(list);
    });
  }
  function groupItem(g) {
    var li = el("li", { class: "gitem" });
    var main = el("div", { class: "gmain" }, [
      el("div", { class: "gname", text: g.name }),
      el("div", { class: "gsub", html: t("drinkingOf", g.active_count | 0, g.member_count | 0) })   // b1people I-15: the code is the "Kod" line under it (gpage.js)
    ]);
    // Design pass 2: the name gets the full row; "Visa kod" below it; "Lämna" is a quiet text button at the
    // bottom of the card (after the module buttons), behind the same confirm. Never next to a common button.
    var leave = el("button", { type: "button", class: "g-leave", text: t("leave") });
    var wrap = el("div", {}, [main, el("div", { class: "g-acts" }, [
      btn(t("show"), "btn-small", function () { showCode(g, false); })
    ])]);
    leave.addEventListener("click", function () {
        if (wrap.querySelector(".confirm")) return;
        var box = el("div", { class: "confirm" }, [
          el("p", { text: t("leaveQ", g.name) }),
          el("div", { class: "row" }, [
            btn(t("cancel"), "btn-small", function () { box.remove(); }),
            btn(t("leaveYes"), "btn-small btn-danger", function () {
              rpc("leave_group", { p_group_id: g.id }).then(function (r) {
                if (r.error) { toast(errMsg(r.error), { err: true }); return; }
                toast(t("left")); refresh(); showGroups();
              });
            })
          ])
        ]);
        wrap.appendChild(box);
        box.scrollIntoView({ block: "nearest" });
    });
    li.appendChild(wrap);
    li.style.display = "block";
    mods("groupItem", g, wrap, main);   // chat button + tap for group status
    wrap.appendChild(el("div", { class: "g-foot" }, [leave]));
    return li;
  }
  function showCreate() {
    withName(function () {
      openSheet(t("create"), function (body) {
        var inp = el("input", { class: "inp", id: "gname-inp", maxlength: "40", enterkeyhint: "done" });
        var go = function () {
          var n = (inp.value || "").trim();
          if (n.length < 1 || n.length > 40) { toast(t("groupNameNeeded"), { err: true }); return; }
          rpc("create_group", { p_name: n, p_display_name: getName() }).then(function (r) {
            if (r.error || !r.data) { toast(errMsg(r.error), { err: true }); return; }
            var g = parseData(r.data);
            refresh(); showGroups(); showGroupPage(g); showCode(g, true);   // ds57: ‹ from the invite = the new group; no toast (the invite card says it, a toast covered the QR)
          });
        };
        inp.addEventListener("keydown", function (e) { if (e.key === "Enter") go(); });
        body.appendChild(el("label", { class: "fld", for: "gname-inp", text: t("groupName") }));
        body.appendChild(inp);
        body.appendChild(el("div", { class: "row", style: "margin-top:12px" }, [
          btn(t("cancel"), "", showGroups), btn(t("create"), "btn-amber", go)
        ]));
        setTimeout(function () { inp.focus(); }, 50);
      });
    });
  }
  // ds59: after a good join, open the new group with its full row from a fresh my_groups
  function openJoined(g) {
    if (!g || !g.id) return;
    rpc("my_groups", {}).then(function (r) {
      var gs = r && !r.error ? parseData(r.data) : null, x = Array.isArray(gs) ? gs.filter(function (y) { return String(y.id) === String(g.id); })[0] : null;
      if (x && Array.isArray(gs) && gs.length > 1) showGroupPage(x);
    });
  }
  function showJoin(code) {
    withName(function () {
      openSheet(t("join"), function (body) {
        var inp = el("input", { class: "inp code-inp", id: "code-inp", maxlength: "200", autocapitalize: "characters", placeholder: "t.ex. ABC234",   // ds59: a link fits
          autocomplete: "off", autocorrect: "off", spellcheck: "false", enterkeyhint: "go", value: U.cleanCode(code) });
        inp.addEventListener("input", function () {
          var raw = String(inp.value || "").replace(/\s+/g, "").toUpperCase();
          if (/[\/:=?&]/.test(inp.value)) return;   // ds59: a pasted link stays as it is (the code is read on Gå med)
          var c = U.cleanCode(inp.value); if (c !== inp.value) inp.value = c;
          // QA #14: a typed character was dropped (O, 0, I, 1 or a symbol): say why, under the field.
          if (raw.length > c.length && c.length < 6) codeHint.hidden = false;
        });
        var codeHint = el("p", { class: "muted code-hint", hidden: "", "aria-live": "polite",
          text: I.lang === "en" ? "Codes have no O, 0, I or 1." : "Koder har inte O, 0, I eller 1." });
        var go = function () {
          var c = U.codeFrom ? U.codeFrom(inp.value) : U.cleanCode(inp.value);   // ds59
          if (c.length !== 6) { toast(t("codeNeeded"), { err: true }); return; }
          rpc("join_group", { p_code: c, p_display_name: getName() }).then(function (r) {
            if (r.error && window.EVLINK && /group_not_found/.test(JSON.stringify(r.error))) {   // social2: an event code?
              var e0 = r.error;
              window.EVLINK.tryCode(c).then(function (ok) { if (!ok) toast(errMsg(e0), { err: true }); });
              return;
            }
            if (r.error) { toast(errMsg(r.error), { err: true }); return; }
            var g = parseData(r.data);
            toast(t("joined", g.name || "")); refresh();
            // In the browser: show how to put the app on the home screen first (the groups are there after).
            showGroups(); openJoined(g);   // ds59: fresh list (the join made the cache dirty) + the new group
            if (!U.isStandalone() && !(window.JOIN && window.JOIN.handled())) toast(I.lang === "en" ? "Tip: put PintsNow on your home screen." : "Tips: lägg PintsNow på hemskärmen.", { ms: 9000, id: "inst", action: { label: I.lang === "en" ? "Show how" : "Visa hur", fn: function () { showInstallGuide(); } } });   // ds59: group first, install later
            document.dispatchEvent(new CustomEvent("pn:group-joined", { detail: { name: g.name || "" } }));   // ntf: calm ask (push.js prime); old push.js: the box
            if (!(window.PUSH && window.PUSH.prime)) notifPromptOnce();
          });
        };
        inp.addEventListener("keydown", function (e) { if (e.key === "Enter") go(); });
        body.appendChild(el("label", { class: "fld", for: "code-inp", text: t("joinCode") }));
        body.appendChild(inp);
        body.appendChild(codeHint);
        body.appendChild(el("div", { class: "row", style: "margin-top:12px" }, [
          btn(t("cancel"), "", showGroups), btn(t("join"), "btn-green", go)
        ]));
        setTimeout(function () { inp.focus(); }, 50);
      });
    });
  }
  function showCode(g, isNew) {
    if (window.JOIN && window.JOIN.openGroup) { window.JOIN.openGroup(g, isNew); return; }   // join.js: one invite sheet
    openSheet(g.name, function (body) {
      var link = joinLink(g.code);
      body.appendChild(el("p", { class: "muted", text: t("joinCode") }));
      body.appendChild(el("div", { class: "code-big", text: g.code }));
      var qr = el("div", { class: "qr", id: "qr", "aria-hidden": "true" });
      body.appendChild(qr);
      try {
        if (window.QRCode) new window.QRCode(qr, { text: link, width: 184, height: 184, colorDark: "#0b1030", colorLight: "#ffffff", correctLevel: window.QRCode.CorrectLevel.M });
        else qr.remove();
      } catch (e) { qr.remove(); }
      var row = el("div", { class: "row", style: "margin-top:8px" }, [
        btn(t("copy"), "", function () { copyText((window.CARDS && window.CARDS.joinUrl(g.code)) || link); })
      ]);
      if (navigator.share) {
        row.appendChild(btn(t("share"), "btn-amber", function () {
          navigator.share({ title: "PintsNow", text: t("shareText", g.name), url: (window.CARDS && window.CARDS.joinUrl(g.code)) || link }).catch(function () {});
        }));
      }
      body.appendChild(row);
      body.appendChild(el("div", { class: "row", style: "margin-top:8px" }, [btn(t("done"), "btn-block", showGroups)]));
      if (isNew) notifPromptOnce(body);
    });
  }
  $("btn-groups").addEventListener("click", showGroups);

  /* ---------- Top list tonight ---------- */
  var topTab = U.ls.get("olnu.topTab", "bars");
  function lvlIcon(l) { return l === 2 ? "🚁" : l === 1 ? "🔥" : ""; }
  function cityOf(b) { var c = window.CITIES.nearest(b.lat, b.lng); return c ? c.name : null; }
  function topRows(kind) {
    if (kind === "bars") {
      var per = window.BARS.assign(PN.s.beers).perBar;
      return Object.keys(per).map(function (k) { return per[k]; })
        .sort(function (a, b) { return b.beers.length - a.beers.length; })   // SAFE: people, never drink level
        .slice(0, 15).map(function (a) {
          var sk = 0; a.beers.forEach(function (b) { sk += skalCount(b); });
          return { name: a.bar.name || t("unnamedBar"), sub: barTypeLabel(a.bar.type) + (sk ? " · " + t("skalN", sk) : ""),
            n: a.beers.length, icon: "", lat: a.bar.lat, lng: a.bar.lng, z: 17,   // SAFE: no 🔥/🚁 by count
            friend: a.beers.some(function (b) { return b.friend_name; }) };
        });
    }
    if (kind === "cities") {
      var g = {};
      beerOnly().forEach(function (b) {
        var c = cityOf(b), k = c || "";
        var x = g[k] || (g[k] = { name: c || t("other"), list: [], other: !c });
        x.list.push(b);
      });
      // Ranked by average beers per person (people = everyone who reported tonight).
      var avgOf = function (x) { var tot = 0; x.list.forEach(function (b) { tot += b.beer_count | 0; }); return x.list.length ? tot / x.list.length : 0; };
      return Object.keys(g).map(function (k) { return g[k]; })
        .sort(function (a, b) { return (a.other - b.other) || (avgOf(b) - avgOf(a)) || b.list.length - a.list.length; })
        .slice(0, 20).map(function (x) {
          var c = null; window.CITIES.list.forEach(function (cc) { if (cc.name === x.name) c = cc; });
          var lat = 0, lng = 0; x.list.forEach(function (b) { lat += b.lat; lng += b.lng; });
          var tot = 0; x.list.forEach(function (b) { tot += b.beer_count | 0; });
          var avg = avgOf(x);
          var avgTxt = (Math.round(avg * 10) / 10).toString().replace(".", I.lang === "sv" ? "," : ".");
          return { name: x.name, sub: t("cityAvgSub", x.list.length, tot), n: avgTxt + " 🍺/" + t("perPerson"), icon: lvlIcon(maxLevel(x.list)),
            lat: c ? c.lat : lat / x.list.length, lng: c ? c.lng : lng / x.list.length, z: c ? 12 : 7,
            friend: x.list.some(function (b) { return b.friend_name; }) };
        });
    }
    return PN.s.beers.filter(function (b) { return U.level(U.drinks(b)) > 0; })
      .sort(function (a, b) { return U.drinks(b) - U.drinks(a); })
      .slice(0, 20).map(function (b) {
        return { name: whoOf(b), sub: placeLabel(b), n: U.drinks(b), icon: lvlIcon(U.level(U.drinks(b))),
          lat: b.lat, lng: b.lng, z: 17, id: b.id, friend: !!b.friend_name, mine: !!b.is_mine };
      });
  }
  function showTop() {
    openSheet(t("top"), function (body) {
      var tabs = el("div", { class: "tabs", role: "tablist" });
      var list = el("ol", { class: "toplist" });
      var note = el("p", { class: "muted top-note" });
      // SAFE (owner 2026-11-07): no lists that rank drinking (Städer = drinks per person, Streaks = people by drinks,
      // Ligan = groups by drinks). Barer = how many people are at each bar.
      var kinds = [["bars", t("topBars")]];
      var league = false;
      if (topTab !== "bars") topTab = "bars";
      if (league) { kinds.push(["league", t("topLeague")]); tabs.classList.add("t4"); }
      else if (topTab === "league") topTab = "bars";
      function draw() {
        tabs.querySelectorAll("button").forEach(function (b) { b.setAttribute("aria-selected", String(b.getAttribute("data-k") === topTab)); });
        list.innerHTML = "";
        if (topTab === "league") { note.textContent = ""; window.SOCIAL.drawLeague(list, note); return; }
        var rows = topRows(topTab);
        note.textContent = topTab === "bars" ? t("topNote") : "";
        if (!rows.length) {
          list.appendChild(el("li", { class: "muted top-empty", text: topTab === "bars" ? t("topNoBars") : topTab === "cities" ? t("topNoCities") : t("topNoStreaks") }));
          return;
        }
        rows.forEach(function (r, i) {
          var li = el("li", {}, [el("button", { type: "button", class: "top-row" + (r.friend ? " friend" : "") + (r.mine ? " mine" : ""),
            onclick: function () { flyTo(r.lat, r.lng, r.z, r.id); } }, [
            el("span", { class: "top-rank", text: String(i + 1).padStart(2, "0") }),
            el("span", { class: "top-main" }, [el("span", { class: "top-name", text: r.name }), el("span", { class: "top-sub", text: r.sub })]),
            el("span", { class: "top-n", text: (r.icon ? r.icon + " " : "") + r.n + (topTab === "streaks" ? " 🍺" : "") })
          ])]);
          list.appendChild(li);
        });
      }
      kinds.forEach(function (k) {
        tabs.appendChild(el("button", { type: "button", role: "tab", "data-k": k[0], text: k[1], onclick: function () {
          topTab = k[0]; U.ls.set("olnu.topTab", topTab); draw();
        } }));
      });
      body.appendChild(tabs); body.appendChild(list); body.appendChild(note);
      draw();
      mods("topSheet", body);   // v12: "Vad dricker stan?"
    });
  }
  $("btn-top").addEventListener("click", showTop);
})();
